CREATE OR REPLACE FUNCTION public.accept_business_invitation(invite_token_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare inv public.organization_invitations%rowtype;
declare member_count integer;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;

  select * into inv from public.organization_invitations
  where token_hash = invite_token_hash and accepted_at is null and expires_at > now()
  limit 1;
  if inv.id is null then raise exception 'Invitation is invalid or expired'; end if;
  if lower(inv.email) <> lower(coalesce((select email from auth.users where id = auth.uid()), '')) then
    raise exception 'Invitation email does not match signed-in account';
  end if;

  select count(*) into member_count from public.organization_members where organization_id = inv.organization_id;
  if member_count >= 5 then raise exception 'Included Business seat limit reached'; end if;

  insert into public.organization_members(organization_id, user_id, role)
  values (inv.organization_id, auth.uid(), inv.role)
  on conflict (organization_id, user_id) do update set role = excluded.role;

  update public.organization_invitations set accepted_at = now() where id = inv.id;
  insert into public.organization_audit_log(organization_id, actor_user_id, action, entity_type, entity_id)
  values (inv.organization_id, auth.uid(), 'member.joined', 'user', auth.uid()::text);
  return inv.organization_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_business_organization(org_name text, org_slug text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare new_id uuid;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if not exists(select 1 from public.profiles where id = auth.uid() and plan = 'business') then raise exception 'Business plan required'; end if;
  if exists(select 1 from public.organization_members where user_id=auth.uid() and role='owner') then raise exception 'Business account already owns an organization'; end if;
  insert into public.organizations(name, slug, owner_user_id) values (trim(org_name), lower(trim(org_slug)), auth.uid()) returning id into new_id;
  insert into public.organization_members(organization_id, user_id, role) values (new_id, auth.uid(), 'owner');
  insert into public.organization_audit_log(organization_id, actor_user_id, action, entity_type, entity_id) values (new_id, auth.uid(), 'organization.created', 'organization', new_id::text);
  return new_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.organization_owner_fence_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'organization identity is immutable'; END IF;
 IF NEW.owner_user_id IS DISTINCT FROM OLD.owner_user_id
 AND NOT public.has_org_role(OLD.id,ARRAY['owner']) THEN
  RAISE EXCEPTION 'organization ownership requires owner';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.accept_business_invitation(invite_token_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE inv public.organization_invitations%rowtype; member_count integer;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
 SELECT * INTO inv FROM public.organization_invitations WHERE token_hash=invite_token_hash;
 IF inv.id IS NULL THEN RAISE EXCEPTION 'Invitation is invalid or expired'; END IF;
 -- Shared organization lock serializes admissions across distinct invitation rows.
 PERFORM 1 FROM public.organizations WHERE id=inv.organization_id FOR UPDATE;
 SELECT * INTO inv FROM public.organization_invitations WHERE id=inv.id AND accepted_at IS NULL AND expires_at>now() FOR UPDATE;
 IF inv.id IS NULL THEN RAISE EXCEPTION 'Invitation is invalid or expired'; END IF;
 IF lower(inv.email)<>lower(coalesce((SELECT email FROM auth.users WHERE id=auth.uid()),'')) THEN RAISE EXCEPTION 'Invitation email does not match signed-in account'; END IF;
 SELECT count(*) INTO member_count FROM public.organization_members WHERE organization_id=inv.organization_id;
 IF member_count>=5 THEN RAISE EXCEPTION 'Included Business seat limit reached'; END IF;
 INSERT INTO public.organization_members(organization_id,user_id,role) VALUES(inv.organization_id,auth.uid(),inv.role)
 ON CONFLICT(organization_id,user_id) DO UPDATE SET role=excluded.role;
 UPDATE public.organization_invitations SET accepted_at=now() WHERE id=inv.id;
 INSERT INTO public.organization_audit_log(organization_id,actor_user_id,action,entity_type,entity_id) VALUES(inv.organization_id,auth.uid(),'member.joined','user',auth.uid()::text);
 RETURN inv.organization_id;
END $function$

